from pathlib import Path
import re
p=Path('caso001-rev01/index.html')
s=p.read_text()
if 'P2.12D.10 · CINEMATIC REVEAL' in s:
    raise SystemExit('D10 already applied')

css=r'''
/* P2.12D.10 · CINEMATIC REVEAL */
.solutionCinematicPanel{padding:0;overflow:hidden;border-color:#4d614d;background:#090b09}.revealHero{position:relative;padding:22px 21px 20px;background:radial-gradient(circle at 78% 10%,rgba(73,120,82,.2),transparent 31%),linear-gradient(160deg,#142018,#0b0e0b 56%,#15100e);border-bottom:1px solid #3f5141}.revealHero.partial{background:radial-gradient(circle at 78% 10%,rgba(152,126,55,.18),transparent 31%),linear-gradient(160deg,#201d11,#0d0c09 60%)}.revealHero.failed{background:radial-gradient(circle at 78% 10%,rgba(132,48,47,.2),transparent 31%),linear-gradient(160deg,#211315,#0d0a0a 60%)}.revealKicker{font-size:8px;letter-spacing:.21em;color:#8cac91;font-weight:950}.revealHero.partial .revealKicker{color:#c3a65d}.revealHero.failed .revealKicker{color:#c37a76}.revealHero h2{font-family:Impact,'Arial Narrow',sans-serif;text-transform:uppercase;font-size:clamp(38px,7vw,68px);line-height:.9;margin:7px 0 8px;color:#eef0e7;letter-spacing:.02em}.revealSubtitle{max-width:720px;color:#aeb6aa;font-size:11px;line-height:1.5}.revealStatusSeal{position:absolute;right:18px;top:18px;border:3px solid rgba(91,155,105,.52);color:#9ed3a9;padding:7px 9px;transform:rotate(-6deg);font-size:11px;letter-spacing:.14em;font-weight:950;text-align:center}.revealHero.partial .revealStatusSeal{border-color:rgba(190,156,68,.5);color:#dcc177}.revealHero.failed .revealStatusSeal{border-color:rgba(185,72,68,.5);color:#e19a95}.revealScore{display:inline-flex;align-items:baseline;gap:5px;margin-top:12px;border:1px solid #3e5844;background:#0d1510;padding:7px 9px}.revealScore strong{font-size:22px;color:#a7d0ad}.revealScore span{font-size:7px;letter-spacing:.1em;color:#75907b}.revealBody{padding:18px 19px 22px}.revealTriad{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.truthCard{border:1px solid #4b4437;background:#12110f;overflow:hidden;min-width:0}.truthImage{height:155px;background:#171511;position:relative;overflow:hidden}.truthImage img{width:100%;height:100%;object-fit:cover;display:block;filter:saturate(.83) contrast(1.04)}.truthCard.person .truthImage img{object-position:center 24%}.truthImage.noImage{display:grid;place-items:center;color:#6f6252;font:700 38px Georgia,serif}.truthImage:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(0,0,0,.72))}.truthCopy{padding:10px 11px 12px}.truthCopy small{font-size:7px;letter-spacing:.13em;color:#88755d;font-weight:950}.truthCopy b{display:block;margin-top:4px;font:700 18px/1.08 Georgia,serif;color:#eadbc8}.revealMotive{margin-top:12px;border:1px solid #775b3d;background:linear-gradient(135deg,#d1bc98,#b3966f);color:#241b13;padding:15px 16px;position:relative}.revealMotive:after{content:"MOTIVO";position:absolute;right:10px;bottom:9px;border:2px solid rgba(117,40,34,.3);color:rgba(117,40,34,.4);padding:3px 7px;transform:rotate(-4deg);font-size:8px;letter-spacing:.1em;font-weight:950}.revealMotive small{display:block;color:#702721;font-size:7px;letter-spacing:.14em;font-weight:950}.revealMotive p{margin:6px 0 0;max-width:860px;font:700 16px/1.5 Georgia,serif}.decisiveContradiction{margin-top:12px;border-left:5px solid #9b312c;background:#1d1110;padding:12px 13px}.decisiveContradiction small{display:block;color:#c26c64;font-size:7px;letter-spacing:.15em;font-weight:950}.decisiveContradiction p{margin:5px 0 0;color:#e0c8c1;font-size:12px;line-height:1.55}.reconstructionTitle{display:flex;align-items:center;gap:10px;margin:20px 0 10px}.reconstructionTitle b{font-size:9px;letter-spacing:.18em;color:#c5a56c}.reconstructionTitle:after{content:"";height:1px;flex:1;background:linear-gradient(90deg,#5e4933,transparent)}.revealFacts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.revealFact{border:1px solid #493a2c;background:#11100e;padding:12px}.revealFact small{display:block;color:#977d5e;font-size:7px;letter-spacing:.12em;font-weight:950;margin-bottom:6px}.revealFact p{margin:0;color:#d2c4b3;font-size:11px;line-height:1.5}.reconstructionSteps{display:grid;gap:0;margin-top:11px}.reconStep{display:grid;grid-template-columns:38px 1fr;gap:10px;position:relative;padding:9px 0}.reconNo{width:32px;height:32px;border:1px solid #6a5238;background:#16120e;display:grid;place-items:center;color:#d4ad6b;font:900 9px/1 ui-monospace,monospace;z-index:1}.reconStep:not(:last-child) .reconNo:after{content:"";position:absolute;top:41px;bottom:-9px;left:15px;width:1px;background:#4b3a2b}.reconText{padding:5px 0;color:#cdbfaf;font-size:11px;line-height:1.52}.redHerrings{margin-top:16px;border:1px dashed #5b4432;background:#0f0d0b;padding:12px}.redHerrings h3{margin:0 0 8px!important;color:#a99073!important;font-size:8px!important;letter-spacing:.15em!important}.redHerring{border-top:1px solid #342a22;padding:8px 0}.redHerring:first-of-type{border-top:0}.redHerring b{font-family:Georgia,serif;color:#d2bca0}.redHerring p{margin:3px 0 0;color:#9e9182;font-size:10px;line-height:1.45}.revealClosing{margin-top:17px;border-top:1px solid #425246;padding-top:14px;font:italic 16px/1.55 Georgia,serif;color:#c7d0c5}.revealClosing:before{content:"CIERRE DEL EXPEDIENTE";display:block;font:900 7px/1 sans-serif;letter-spacing:.16em;color:#78917d;margin-bottom:7px}.revealEndStamp{display:flex;justify-content:flex-end;margin-top:14px}.revealEndStamp span{border:3px solid rgba(91,139,99,.36);color:#82ad8b;padding:6px 9px;transform:rotate(-3deg);font-size:8px;letter-spacing:.13em;font-weight:950}
@media(max-width:820px){.revealTriad,.revealFacts{grid-template-columns:1fr}.truthCard{display:grid;grid-template-columns:125px 1fr}.truthImage{height:120px}.revealStatusSeal{position:static;display:inline-block;margin-top:12px;transform:rotate(-3deg)}.revealHero h2{font-size:44px}}
@media(max-width:460px){.revealBody{padding:13px}.truthCard{grid-template-columns:100px 1fr}.truthImage{height:105px}.truthCopy b{font-size:15px}.revealHero{padding:17px}.revealHero h2{font-size:37px}}
'''
anchor='/* P2.12D.9 · CINEMATIC ACCUSATION */'
if anchor not in s: raise SystemExit('D9 marker missing')
s=s.replace(anchor,css+'\n'+anchor,1)

old='''      <section id="solutionPanel" class="panel hidden"><div id="solutionBody"></div></section>'''
new='''      <section id="solutionPanel" class="panel solutionCinematicPanel hidden"><div id="solutionBody"></div></section>'''
if old not in s: raise SystemExit('solution panel html anchor missing')
s=s.replace(old,new,1)

helpers=r'''function normalizedLabel(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function solutionVisual(labels,images,name){const n=normalizedLabel(name),idx=labels.findIndex(x=>normalizedLabel(x)===n);return idx>=0?images[idx]:''}
function truthCard(kind,label,name,img){return `<article class="truthCard ${kind}"><div class="truthImage ${img?'':'noImage'}">${img?`<img src="${esc(img)}" alt="${esc(name)}">`:'?'}</div><div class="truthCopy"><small>${esc(label)}</small><b>${esc(name||'—')}</b></div></article>`}
'''

pat=re.compile(r'function renderSolution\(\)\{.*?\}\nfunction renderControls\(\)\{',re.S)
m=pat.search(s)
if not m: raise SystemExit('renderSolution anchor missing')
new_render=r'''function renderSolution(){const ev=latestEvent('solution'),panel=$('#solutionPanel');if(!ev){panel.classList.add('hidden');return}panel.classList.remove('hidden');const data=ev.payload||{},status=data.status||'resolved',resolved=status==='resolved',partial=status==='partial',heroClass=partial?'partial':resolved?'':'failed',statusLabel=resolved?'CASO RESUELTO':partial?'RESOLUCIÓN PARCIAL':'ACUSACIÓN FALLIDA',killer=data.killer_character_name||'—',locationName=data.location_name||'—',objectName=data.object_name||'—',killerImg=solutionVisual(P2_LABELS.characters,REV01_PORTRAITS,killer),locationImg=solutionVisual(P2_LABELS.locations,REV01_LOCATION_IMAGES,locationName),objectImg=solutionVisual(P2_LABELS.objects,REV01_OBJECT_IMAGES,objectName),steps=Array.isArray(data.reconstruction)?data.reconstruction:[],herrings=Array.isArray(data.red_herrings)?data.red_herrings:[];$('#solutionBody').innerHTML=`<div class="revealHero ${heroClass}"><div class="revealKicker">EXPEDIENTES · CASO 001 · RECONSTRUCCIÓN OFICIAL</div><h2>${esc(statusLabel)}</h2><div class="revealSubtitle">La solución que sigue proviene del expediente generado y validado por el servidor para esta partida.</div><div class="revealScore"><strong>${Number(data.hits)||0}/3</strong><span>ELEMENTOS DE LA ACUSACIÓN</span></div><div class="revealStatusSeal">${esc(statusLabel)}</div></div><div class="revealBody"><div class="revealTriad">${truthCard('person','RESPONSABLE',killer,killerImg)}${truthCard('location','ESCENA CLAVE',locationName,locationImg)}${truthCard('object','OBJETO CLAVE',objectName,objectImg)}</div><section class="revealMotive"><small>MOTIVO · HIPÓTESIS CAUSAL REAL</small><p>${esc(data.motive||'—')}</p></section>${data.contradiction?`<section class="decisiveContradiction"><small>CONTRADICCIÓN DECISIVA</small><p>${esc(data.contradiction)}</p></section>`:''}<div class="reconstructionTitle"><b>RECONSTRUCCIÓN DEL CASO</b></div><div class="revealFacts"><article class="revealFact"><small>QUÉ OCURRIÓ</small><p>${esc(data.critical_event||'—')}</p></article><article class="revealFact"><small>CÓMO OCURRIÓ</small><p>${esc(data.mechanism||'—')}</p></article><article class="revealFact"><small>ENCUBRIMIENTO</small><p>${esc(data.post_crime_action||'—')}</p></article></div>${steps.length?`<div class="reconstructionSteps">${steps.map((x,i)=>`<div class="reconStep"><span class="reconNo">${String(i+1).padStart(2,'0')}</span><div class="reconText">${esc(x)}</div></div>`).join('')}</div>`:''}${herrings.length?`<section class="redHerrings"><h3>SEÑUELOS EXPLICADOS</h3>${herrings.map(x=>`<div class="redHerring"><b>${esc(x.title||'Señuelo')}</b><p>${esc(x.resolution||'')}</p></div>`).join('')}</section>`:''}${data.closing?`<div class="revealClosing">${esc(data.closing)}</div>`:''}<div class="revealEndStamp"><span>EXPEDIENTE CERRADO</span></div></div>`}
'''
s=s[:m.start()]+helpers+new_render+'function renderControls(){'+s[m.end():]

p.write_text(s)
print('P2.12D.10 patch complete')
